#include <stdio.h>

int main(void) {
    double celsius;
    // read celsius, convert, print
    return 0;
}

solution:
#include <stdio.h>

int main(void) {
    double celsius;
    scanf("%lf", &celsius);
    double kelvin = celsius + 273.15;
    printf("K: %.2f\n", kelvin);
    return 0;
}
